#' This is a function to build preset hypotheses for the GORIC wrapper function to be used
#'
#' @param hypothesis.set A list of strings containing names of sets of pre-defines hypotheses
#' @param parnames A vector of strings containing valid parameter names. These are used to define hypotheses
#'
#' @returns A list of hypotheses as strings:
#' @export
#'
#' @example
#' parnames = c("adjmean0", "adjmean1") # This will normally be generated by estimand.to.parnames()
#' build_hypotheses(parnames=parnames)
build_hypotheses <- function(hypothesis.set=NULL, parnames) {
# Validate Predefined Hypotheses ------------------------------------------
  validate.hypotheses(hypothesis.set)

  preset.hypotheses <- list()

# Split parameters into Sub-Groups ----------------------------------------
  groups <- list(
    # A list of 4 character vectors
    # groups$adjmeans is: chr [1:2] "adjmean0" "adjmean1"
    # groups$ATE is: character(0)
    adjmeans = grep("^adjmean", parnames, value = TRUE),
    ATE      = grep("^Eg", parnames, value = TRUE),
    ATT      = grep("^ATT", parnames, value = TRUE),
    ATC      = grep("^ATC", parnames, value = TRUE)
  )



# Default Hypotheses ------------------------------------------------------

  if (is.null(hypothesis.set)){
    # This means we do it if there are no predefined Hypothesis, so to say a default option
    ## Fully Ordered parameters
    preset.hypotheses <- lapply(groups, function(x){
      # for each group of parameters that includes more than 1, make 2 seperate hypotheses, one fully ordered > and one fully ordered <
      if (length(x) > 1){
        list(
          descending = paste(x, collapse = " > "),
          ascending = paste(x, collapse = " < ")
        )
      }
    })

    # Flatten from preset.hypotheses$adjmeans$gt to preset.hypotheses$adjmeans.gt
    preset.hypotheses <- unlist(preset.hypotheses, recursive = FALSE)
  }



  ## If a set of the preset hypotheses was specified then we filter them here

  ## Ordered Hypothesis
  if ("ordering.asc" %in% hypothesis.set) {
    preset.hypotheses$h.order <- paste(parnames, collapse = " > ")
  }

  ## ATT > ATC Hypothesis
  if ("ATT_gt_ATC" %in% hypothesis.set) {
    ## TODO: add this
  }

  ## Hypotheses about the Effect Size of an Effect

  ## Hypotheses about minimal differences
    # eg mu1 - mu0 > 0.2 or so


  ## Hypotheses about particular covariates
  # like test for all coefficients of that specified covariate all in one
  # Think elr allows that as "user specified tests" via wald test

  return(preset.hypotheses)
}
